    fk=16*fields;fc=16*contexts
    # Independent semantic filtering of source columns, including action and context.
    expected_sc=[i for i in range(4*fk) if i%16 in keep]+list(range(4*fk,4*fk+16))
    expected_tw=list(range(fc))+[i for i in range(fc,fc+2*fk) if (i-fc)%16 in keep]+list(range(fc+2*fk,fc+2*fk+16))
    assert sc==expected_sc and tw==expected_tw
    assert len(sc)==4*fields*width+16 and len(tw)==fc+2*fields*width+16
    assert len(sc)==len(set(sc)) and len(tw)==len(set(tw))
 # Check local-only metadata with item aliases and cross-source alias protection.
 class Map:pass
 fm=Map();fm.features={'item_id':{'type':'categorical','source':'item','vocab_size':9},'other_item':{'type':'categorical','source':'item','share_embedding':'item_id','vocab_size':9},'u':{'type':'categorical','source':'user','vocab_size':5},'a':{'type':'categorical','source':'action','vocab_size':8}}
 before=copy.deepcopy(fm.features);local,widths=ns['_capacity_layout'](fm,14,16)
 assert fm.features==before and local is not fm and local.features is not fm.features
 assert widths=={'item_id':14,'other_item':14,'u':16,'a':16}
 fm.features['u']['share_embedding']='item_id'
 _,widths=ns['_capacity_layout'](fm,14,16)
 assert widths['item_id']==widths['other_item']==widths['u']==16
 # The native constructor explicitly rejects this protected cross-source alias layout.
 imports=[]
 for n in ast.walk(tree):
  if isinstance(n,ast.Import):imports.extend(x.name for x in n.names)
  if isinstance(n,ast.ImportFrom):imports.append(n.module)
 assert all(x.split('.')[0] in ('copy','torch','unirank') for x in imports)
 config=ast.literal_eval(next(n.value for n in tree.body if isinstance(n,ast.Assign) and any(isinstance(t,ast.Name) and t.id=='CONFIG' for t in n.targets)))
 print(file, 'width',config['item_embedding_dim'],'selection',config['item_coordinate_selection'],'sha256',hashlib.sha256(Path(file).read_bytes()).hexdigest())
print('PASS: syntax, inherited-operator AST equality, constructor/copy-body identity, coordinate/semantic-column mapping, invalid inputs, local metadata and alias protections, import boundary.')
print('torch_available',importlib.util.find_spec('torch') is not None)
print('jsonschema_available',importlib.util.find_spec('jsonschema') is not None)
